-- The palette generated by `ocarina-theme` (templates/nvim/palette.lua → ~/.local/state/ocarinashell/theme/).
-- If it is missing or broken (fresh install, a half-written file) Neovim still starts with the 墨 Sumi defaults.
local M = {}

M.dir = (vim.env.XDG_STATE_HOME or (vim.env.HOME .. "/.local/state")) .. "/ocarinashell/theme"
M.file = M.dir .. "/palette.lua"

local fallback = {
  id = "sumi",
  name = "Sumi",
  kanji = "墨",
  mode = "dark",
  bg = "#0e0e0f",
  surface0 = "#161617",
  surface1 = "#1c1c1e",
  surface2 = "#252527",
  surface3 = "#2f2f32",
  outline = "#2a2a2d",
  outline_strong = "#444448",
  text = "#ecebe8",
  text_muted = "#a3a19d",
  text_dim = "#6b6966",
  accent = "#e60033",
  accent_hover = "#ff1f4f",
  accent_soft = "#e60033",
  on_accent = "#ffffff",
  accent2 = "#b7b1a6",
  success = "#8fb79a",
  warning = "#d9b25c",
  error = "#ff4d6a",
  info = "#9bb7c9",
  asagi = "#00a3af",
  selection = "#3a2a2e",
  cursor = "#e60033",
  term = {
    "#1c1c1e",
    "#e60033",
    "#8fb79a",
    "#d9b25c",
    "#8ea4bf",
    "#b49ab8",
    "#8fb5b8",
    "#c9c7c2",
    "#55555a",
    "#ff4d6a",
    "#a9cbb2",
    "#e8c87f",
    "#a9bbd1",
    "#c8b3cb",
    "#a7c8ca",
    "#ecebe8",
  },
}

local function valid(p)
  if type(p) ~= "table" or type(p.term) ~= "table" or #p.term ~= 16 then return false end
  for k, v in pairs(fallback) do
    if type(v) == "string" and k ~= "id" and k ~= "name" and k ~= "kanji" and k ~= "mode" then
      if type(p[k]) ~= "string" or not p[k]:match("^#%x%x%x%x%x%x$") then return false end
    end
  end
  return true
end

---@return table palette, boolean from_file
function M.load()
  local chunk = loadfile(M.file)
  if chunk then
    local ok, p = pcall(chunk)
    if ok and valid(p) then return p, true end
  end
  return fallback, false
end

return M
